contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking parameters to control funding and a seed to vary behavior
    function run(uint256 seedDeposit, uint256 fundAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // Ensure this test contract has enough Ether to fund sending fundAmount to c if requested.
        // We require that fundAmount does not exceed this contract balance to avoid underflow in external transfers.
        require(address(this).balance >= fundAmount);

        // Read before-values
        uint256 beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint256 beforeBal = address(c).balance;

        // Optionally fund c by sending Ether directly to it using its fallback via a top-level call on c: call with empty calldata invokes fallback.
        // The constraints require state-changing calls on c to be top-level; using address(c).call is not a call on c via its contract type,
        // so instead we use the fact that this contract is the owner and can cause c to receive Ether by using sendMoney to a payable fallback of c itself.
        // But sendMoney calls an external target. To deposit into c we can call c.sendMoney targeting address(c) with the provided fundAmount and empty data.
        // c.sendMoney is onlyOwner and this contract is owner, so it's allowed. Ensure we only attempt when fundAmount > 0.
        if (fundAmount > 0) {
            // Ensure c has sufficient balance to send fundAmount to itself: if c.balance < fundAmount, the call will revert inside c.sendMoney.
            // To avoid that revert (which would block reaching the final assert), only perform the sendMoney when fundAmount <= beforeBal + fundAmount
            // but we cannot increase c.balance except via this call. So we instead first transfer Ether from this contract into c by calling c with value using low-level call on address(c).
            // However low-level calls are not allowed by the template as state-changing calls must be of form c.f(...). Given limitations, we avoid trying to seed c: we only call withdrawAll and reason about its effect even if balance is zero.
        }

        // Call withdrawAll as owner (this contract is the owner). Capture whether it reverted.
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after-values
        uint256 afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint256 afterBal = address(c).balance;

        // The general rule: when the owner (this contract) calls withdrawAll it must not revert, depositsCount must be unchanged, and the contract balance must be zero afterwards.
        // Also, if there was any balance before, that balance must have been transferred to this contract (so this contract's balance increases by at least beforeBal - afterBal == beforeBal).
        // Since we cannot reliably observe pre-balance of this contract in a view call, we assert the core properties accessible: no revert, depositsCount unchanged, and c.balance == 0.
        assert(reverted == false && afterCount == beforeCount && afterBal == 0);
    }

    // Allow receiving Ether so withdrawAll can transfer here
    receive() external payable {}
}

