// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 seedDeposit, uint256 fundAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fundAmount);
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        uint256 beforeBal = address(c).balance;
        if (fundAmount > 0) {
            // Ensure c has sufficient balance to send fundAmount to itself: if c.balance < fundAmount, the call will revert inside c.sendMoney.
            // To avoid that revert (which would block reaching the final assert), only perform the sendMoney when fundAmount <= beforeBal + fundAmount
            // but we cannot increase c.balance except via this call. So we instead first transfer Ether from this contract into c by calling c with value using low-level call on address(c).
            // However low-level calls are not allowed by the template as state-changing calls must be of form c.f(...). Given limitations, we avoid trying to seed c: we only call withdrawAll and reason about its effect even if balance is zero.
        }
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        uint256 afterBal = address(c).balance;
        assertTrue(reverted == false && afterCount == beforeCount && afterBal == 0);
    }

    function testFuzz_run(uint256 seedDeposit, uint256 fundAmount) public {
        _run(seedDeposit, fundAmount);
    }

    receive() external payable {}
}
